from pathlib import Path
import re
syn = Path('synonyms.txt').read_text().splitlines()
allowed = {}
for line in syn:
    parts = [p.strip() for p in line.split(',') if p.strip()]
    if not parts:
        continue
    for p in parts:
        allowed.setdefault(p, parts)
text = Path('input.tex').read_text()
def repl(m):
    w = m.group(0)
    low = w.lower()
    if low in allowed:
        cands = [c for c in allowed[low] if c.lower() == c]  # prefer lowercase
        if not cands:
            cands = allowed[low]
        best = min(cands, key=len)
        if best != low and len(best) < len(low):
            if w[0].isupper():
                best = best.capitalize()
            return best
    return w
new = re.sub(r'[A-Za-z]+', repl, text)
Path('input.tex').write_text(new)
print(new[:4000])
